-- 032_sandhed.sql
-- Sandhed (digital tvilling-platform, Gzira, Malta). Data fra sandhed.com, 6. okt. 2026.
-- 10 x 6 måneders gratis Sandhed: timepræmie sammen med vinen på konferencen (vilkår pkt. 9)
-- og én adgang i den store pulje. Værdien er ikke bekræftet endnu, så gaven står uden
-- værdi og kommer først i puljen, når værdien er lagt ind.
-- Kun i den rigtige database (hvor Zignifikant findes), ikke i en tom testdatabase.

INSERT INTO partner (id, slug, status, vist_i_spil, navn, firmanavn, cvr, adresse, hjemmeside,
                     kort_beskrivelse, produktkategori, privatlivspolitik, afmeld_email,
                     kontakt_email, levering_email,
                     giver_praemie, praemie_titel, praemie_beskrivelse, praemie_flyt, logo, logo_type)
SELECT gen_random_uuid(), 'sandhed', 'aktiv', true, 'Sandhed', 'Sandhed', '', 'Gzira, Malta', 'https://www.sandhed.com/da',
       'Sandhed gør plantegningen og live driftsdata til en 3D digital tvilling, så I kan se hele lageret og driften live og finde udstyr og paller med det samme.',
       'digital tvilling og 3D-overblik over lager og drift', 'https://www.sandhed.com/da/privacy', 'hello@sandhed.com',
       'hello@sandhed.com', 'hello@sandhed.com',
       true, '6 måneders gratis Sandhed', 'Vinderen får 6 måneders gratis adgang til Sandhed, den digitale tvilling-platform med live 3D-overblik over lager og drift.', 'spoerg',
       decode('', 'base64'), 'image/png'
WHERE NOT EXISTS (SELECT 1 FROM partner WHERE slug = 'sandhed')
  AND EXISTS (SELECT 1 FROM partner z WHERE lower(z.navn) = 'zignifikant');
